def _search_for_values(key, json_obj):
    """
    Function yields values of a given key

    :param key str: key of searched value
    :param json_obj dict: searched object
    """

    def recurse_search(json_obj, res_acc=None):
        if isinstance(json_obj, dict):
            [res_acc.append(value) if k == key else recurse_search(value, res_acc) for k, value in json_obj.items()]
        elif isinstance(json_obj, list):
            [recurse_search(item, res_acc) for item in json_obj]
        return res_acc
    return recurse_search(json_obj, res_acc=list())


def search_for_values(key, json_obj):
    """
    Returns list of values corresponding to provided key

    :param key:
    :param json_obj:
    :return:
    """
    return _search_for_values(key, json_obj)


def find_first_occurrence(key_list, json_obj):
    """
    Searches for any occurrence of any of the given keys
    and returns first found object.
    :param key_list: list of keys to check
    :param json_obj: searched object
    :return:
    """
    for key in key_list:
        found_list = search_for_values(key, json_obj)
        if len(found_list) > 0:
            return found_list[0]
    return None


class MZErrorHandler(object):
    _ERR_CODE_KEYS = ['errno', 'code', 'errorCode']
    _MESSAGE_KEYS = ['message', 'userMessage', 'developerMessage']
    _msg = {-2: 'Probably BTS is not commissioned'}

    @classmethod
    def get_error_code(cls, err_response):
        """
        Searches for error code in http error response.

        :param err_response: response object of the http request
        :return: error code or None if code wasn't found or
        response content type isn't json.
        """
        if err_response.headers['content-type'] == 'application/json':
            content = err_response.json()
            return find_first_occurrence(cls._ERR_CODE_KEYS, content)
        else:
            return None

    @classmethod
    def get_error_message(cls, code, err_response):
        """
        Searches for error message in http error response.

        :param code: Desired error code, if this parameter is not None,
        method returns appropriate message from classes _msg dictionary
        :param err_response: response object of the http request
        :return: if given error code isn't in _msg dictionary or is
        None method returns message from response json content or
        error content as text if content type isn't json.
        """
        if err_response.headers['content-type'] == 'application/json':
            content = err_response.json()
            return cls._msg.get(code) or find_first_occurrence(cls._MESSAGE_KEYS, content)
        elif 'text' in err_response.headers['content-type']:
            return err_response.text
        else:
            return str(err_response.content)
